            // 按需加载 / 插件语言包（v0.0.89）
            'i18n.loadFail': '语言包加载失败，已回退中文',
            'i18n.fromPlugin': '插件',
            'i18n.needDownload': '需下载',
            'i18n.pluginLangAdded': '插件注册了新语言',
            's.dashboard': "仪表盘",
