            's.tasksHint': "上传、下载、分享、整理仓库都会出现在这里",
            's.pluginSubmit': "访问插件仓库提交你的插件",
            's.loading': "加载中...",
            's.loadSharesFail': "加载分享失败",
            's.loadPluginsFail': "加载插件市场失败",
            's.nSelected': "{n} 项已选",
